def compute(vars):
    total_assets = vars["Total Assets"]
    total_liabilities = vars["Total Liabilities"]
    total_shareholders_equity = total_assets - total_liabilities

    return {
        "value": total_shareholders_equity,
        "trace": {
            "Total Assets": total_assets,
            "Total Liabilities": total_liabilities,
            "Total Shareholders' Equity": total_shareholders_equity,
            "output_meta": {
                "currency": "$",
                "scale": "millions",
                "unit": None
            }
        }
    }
